from __future__ import annotations

import re

_UNIT_SECONDS: dict[str, int] = {'d': 86_400, 'h': 3_600, 'm': 60, 's': 1}

_DURATION_RE = re.compile(r'\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*')


def parse_duration(s: str) -> int:
    """Parse a duration string such as ``'1h30m'`` into a whole number of seconds.

    Units are ``d``, ``h``, ``m`` and ``s``, each appearing at most once and in that order,
    with a non-negative integer amount before each unit. Surrounding whitespace is allowed.

    Raises:
        ValueError: If ``s`` is not a well-formed duration (including the empty string,
            a bare number, a repeated unit, or units out of order).
    """
    match = _DURATION_RE.fullmatch(s)
    if match is None:
        raise ValueError(f'invalid duration: {s!r}')
    amounts = match.groups()
    if all(amount is None for amount in amounts):
        raise ValueError(f'invalid duration: {s!r}')
    return sum(int(amount) * seconds for amount, seconds in zip(amounts, _UNIT_SECONDS.values()) if amount is not None)
"}

